/* RESET ($7D44) - ENTRY 0 DOES A RESET
 * Condition codes in: NZVC; out: C.
 */
void s_reset(void)
{
    CK(0x7D44);
    CYC(4);
    s_firq(); return;                                /* L7D44 */
}

/* MAIN ($7D47) - Mainline loop: enable IRQ, wait for SYNC (4 ms), resetting if RAM, DP or IRQ fail; send watchdog
 *   PBXS_OK to SOUT, count S_INTCT, step test tones if test switch on, then SPKIRQ, DOCMD, FM bit, AUDDO, PKDR
 * Condition codes in: NZVC; out: C.
 */
void s_main(void)
{
    uint16_t ea;
l_main:;
    sw_pass(0x7D47);
    CK(0x7D47);
    sw_cli();                                        /* L7D47  CLI   */
    X = 0x014D;                                      /* L7D49  IRQ TIMEOUT--WAIT ABOUT 8 MILLS(12000. CYCLES) */
    CYC(6);
    do {
        CK(0x7D4C);
        /* DO ALL THE WATCHDOG AND SAFETY THINGS THAT */
        /* IRQ DOESN'T HAVE TIME FOR */
        A = M8(S_GARBG);                             /* L7D4C */
        cmp8(A, 0x3F);                               /* L7D4E */
        CYC(9);
        if (!CCZ) { s_reset(); return; }             /* L7D50  B RESET IF FIRST RAM BYTE GETS BLITZED */
        /* (9 CYCLES) */
        A = DP;                                      /* L7D52 */
        cmp8(A, 0x10);                               /* L7D54 */
        CYC(11);
        if (!CCZ) { s_reset(); return; }             /* L7D56  B RESET IF DPAGE REGISTER GETS CREAMED */
        /* (11 CYCLES) */
        X = (uint16_t)(X - 1);                       /* L7D58 */
        CCZ = (X == 0);
        CYC(8);
        if (CCZ) { s_reset(); return; }              /* L7D5A  B RESET IF IRQ HASN'T BEEN WORKING (TIMED OUT) */
        /* (8 CYCLES) */
        M8(SYNC) = lsr8(M8(SYNC));                   /* L7D5C  NOW WE CHECK IF IRQ HAS KICKED US (EVERY 4 MS) */
        CYC(9);
    } while (!CCC);                                  /* L7D5E  CSEND  (9 CYCLES) */
    /* HERE WE GO!!!! */
    A = PBXS_OK;                                     /* L7D60  THIS IS THE WATCHDOG VALUE */
    CYC(2);
    hw_wr8(SOUT, A);                                 /* L7D62  MAIN PCB CHECKS FOR THIS EVERY VG UPDATE */
    /* AND RESETS SOUND BOARD IF NOT CORRECT */
    M8(S_INTCT) = (uint8_t)(M8(S_INTCT) + 1);        /* L7D65  COUNTER FOR EVERY 4 MILLS */
    CYC(14);
    if (M8(S_INTCT) == 0) {                          /* L7D67  IFEQ   */
        M8(S_INTHI) = (uint8_t)(M8(S_INTHI) + 1);    /* L7D69  SECONDS COUNTER */
        A = 0x03;                                    /* L7D6B  TRY EVERY 4 SECONDS */
        B = M8(DG_SEQ);                              /* L7D6D  B:=DG.SEQ */
        cmp8(B, DGS_VIB);                            /* L7D6F  NOT ONLY VIBRATTO OFF DURING TEST, BUT ALSO */
        /* SEQUENCE MORE SLOWLY */
        CYC(17);
        if (!CCC) {                                  /* L7D71  IFHS  ?NOT DOING TEST TONES ANYMORE? */
            A = 0x01;                                /* L7D73  THEN CYCLE EVERY 2 SECONDS INSTEAD */
            CYC(2);
        }
        A &= M8(S_INTHI);                            /* L7D75 */
        CYC(7);
        if (A == 0) {                                /* L7D77  IFEQ  ?EVERY 2 SECONDS? */
            M8(TESTON) = 0; clrf();                  /* L7D79 */
            CYC(7);
            A = hw_rd8(TESTSW);                      /* L7D7C */
            A &= TESTBT;                             /* L7D7E */
            CYC(9);
            if (A == 0) {                            /* L7D80  IFEQ  ?TEST SWITCH ON?(LO TRUE) */
                M8(TESTON) = (uint8_t)(M8(TESTON) + 1); /* L7D82 */
                /* B:=DG.SEQ */
                B = (uint8_t)(B + 1);                /* L7D85 */
                cmp8(B, PBXS_EQ);                    /* L7D86 */
                CYC(14);
                if (!CCC) {                          /* L7D88  IFHS  ?PAST TOP ENTRY? */
                    B = 0x01;                        /* L7D8A */
                    CYC(2);
                }
                M8(DG_SEQ) = B;                      /* L7D8C  SAVE CURRENT DIAG SEQUENCE */
                X = PBX;                             /* L7D8E  SHOW OFF NEXT PBX ROUTINE */
                X = (uint16_t)(X + B);               /* L7D91 */
                X = (uint16_t)(X + B);               /* L7D92 */
                CYC(23);
                ea = rd16(X);                        /* L7D93  ACTIVATE NEXT ROUTINE */
                S = (uint16_t)(S - 2); call_rom(ea);
            }
        }
    }
    CYC(8);
    JSR(s_spkirq);                                   /* L7D95  START SPEECH AT FRONT */
    CYC(8);
    JSR(s_docmd);                                    /* L7D98  DO ANY NEW COMMANDS */
    /* SET FM DUE TO CURRENT SOUND OUTPUT */
    B = hw_rd8(PAD);                                 /* L7D9B  B:= ORIGINAL OUTPUT VALUE */
    A = M8(SP_DLY);                                  /* L7D9D  DELAY FOR PAUSES IN VOICE */
    A |= M8(SP_STA);                                 /* L7D9F  OR ACTIVELY SPEAKING */
    CYC(15);
    if (A != 0) goto l_main_50;                      /* L7DA1  B FM OFF */
    A = M8(VIU);                                     /* L7DA3  ANY MUSIC IN USE */
    CYC(7);
    if (A != 0) goto l_main_50;                      /* L7DA5  B FM OFF */
    A = M8(TESTON);                                  /* L7DA7 */
    CYC(8);
    if (A != 0) {                                    /* L7DAA  IF NE  TEST SW WAS ON? */
        A = M8(DG_SEQ);                              /* L7DAC */
        CYC(9);
        if (A <= DGS_VIB) goto l_main_50;            /* L7DB0 */
    }
    X = rd16(AUS_PNT+((((5-1)*2)+1)*AUS_IZ)+AU_BLK); /* L7DB2  R2 SOUNDS ON CHANNEL 5 */
    CYC(13);
    if (X >= VIBOFF) goto l_main_50;                 /* L7DB8 */
    B &= (uint8_t)(-1-BT3);                          /* L7DBA  FM NOT(TURN FM ON) */
    CYC(5);
    goto l_main_58;                                  /* L7DBC */
l_main_50:;
    CK(0x7DBE);
    B |= BT3;                                        /* L7DBE  HI FALSE */
    CYC(2);
l_main_58:;
    CK(0x7DC0);
    hw_wr8(PAD, B);                                  /* L7DC0  SHOVE NEW FM OUT */
    A = M8(S_INTCT);                                 /* L7DC2 */
    A = lsr8(A);                                     /* L7DC4 */
    CYC(13);
    if (!CCC) {                                      /* L7DC5  IFCC  ?8 MILL BOUNDARY? */
        CYC(8);
        JSR(s_auddo);                                /* L7DC7  THEN AUDIO SPECIAL EFFECTS */
    }
    CYC(8);
    JSR(s_pkdr);                                     /* L7DCA  DONT FORGET THE MUSIC (OK, THEN JUST HUM) */
    CYC(8);
    JSR(s_spkirq);                                   /* L7DCD  THEN END WITH SPEECH, TWICE IN 4 MS */
    CYC(4);
    goto l_main;                                     /* L7DD0 */
}

/* DOCMD ($7DD3) - DO ANY NEW COMMANDS
 */
void s_docmd(void)
{
    uint16_t ea;
    CK(0x7DD3);
    B = M8(CMDBTM);                                  /* L7DD3 */
    cmp8(B, M8(CMDTOP));                             /* L7DD5 */
    CYC(11);
    if (!CCZ) {                                      /* L7DD7  IFNE  ?SOME NEW COMMANDS IN BUFFER? */
        B = (uint8_t)(B + 1);                        /* L7DD9 */
        B &= 0x1F;                                   /* L7DDA  HANDLE WRAPAROUND */
        M8(CMDBTM) = B;                              /* L7DDC  JUST HANDLE ONE NEW REQUEST PER IRQ */
        X = CMD;                                     /* L7DDE */
        B = rd8((uint16_t)(X + (int8_t)B));          /* L7DE1  GOT OUR COMMAND */
        nz8(B);
        CYC(21 + ((CCZ) ? 1 : 0));
        if (CCZ) { s_firq(); return; }               /* L7DE3  START OVER IF ZERO COMMAND FOUND */
        /* CMPB PBXS_EQ */                           /* L7DE7  MAX NUMBER ALLOWED VIA PBX */
        CYC(5);
        if (B <= PBXS_EQ) {                          /* L7DE9  IFLS  ?WITHIN RANGE? DROP ON FLOOR IF NOT */
            X = PBX;                                 /* L7DEB */
            X = (uint16_t)(X + B);                   /* L7DEE */
            X = (uint16_t)(X + B);                   /* L7DEF  WORD POINTER, 255 MAX ENTRIES */
            CYC(19);
            ea = rd16(X);                            /* L7DF0  ACTIVATE THE ROUTINE REQUESTED */
            S = (uint16_t)(S - 2); call_rom(ea);
        }
    }
    CYC(5);
    RTS;                                             /* L7DF2 */
}

/* IRQ ($7DF3) - SETUP OUR FAST COMMAND HANDLER
 * Condition codes in: C; out: C.
 */
void s_irq(void)
{
    CK(0x7DF3);
    B = M8(CMDTOP);                                  /* L7DF3  B:=DISP TO LATEST COMMAND */
    X = CMD;                                         /* L7DF5  X-->STORE COMMANDS IN THIS BUFFER */
    CYC(7);
    A = hw_rd8(PAD);                                 /* L7DF8  SAFER TO USE PRESENCE BIT RATHER THAN EDGE BIT */
    CYC(7);
    if ((A & 0x80)) {                                /* L7DFA  IFMI  ?MAINLINE HAVE NEW BYTE FOR US? */
        /* [LDA RIF] ;RIF CLEARS PIA7 EDGE, DONE IN TIMER SECTION */
        A = hw_rd8(SIN);                             /* L7DFC  GET THE COMMAND */
        nz8(A);
        /* TELL OTHER BOARD RIGHT AWAY */
        /* DONT SLOW HIM DOWN */
        CYC(8);
        if (CCZ) { s_firq(); return; }               /* L7DFF  SUPERCOMMAND ZERO SAYS RESET RIGHT NOW */
        /* X-->COMMAND BUFFER */
        /* B:= DISP INTO COMMAND BUFFER, LATEST COMMAND */
        B = (uint8_t)(B + 1);                        /* L7E01 */
        B &= 0x1F;                                   /* L7E02  ROOM FOR PRECISELY 32. */
        wr8((uint16_t)(X + (int8_t)B), A);           /* L7E04 */
        CYC(9);
    }
    /* NOW FOR SOME FAST FOOTWORK TO HANDLE */
    /* FAST SEQUENTIAL REQUESTS */
    /* AND OUR SLOW IRQ LATENCY */
    /* X-->COMMAND BUFFER */
    /* B:= DISP INTO COMMAND BUFFER, LATEST COMMAND */
    /* FIRST HANDLE ANY TIMER INTERRUPT */
    A = hw_rd8(RIF);                                 /* L7E06  RIF D7==>TIMER, D6==>PIA GOT SOME NEW DATA */
    /* READING CLEARS PIA FLAG */
    /* ***THIS WILL CLEAR ANY PREVIOUS NEW DATA IRQ */
    CYC(7);
    if ((A & 0x80)) {                                /* L7E08  IFMI  ?TIMER CAUSED? */
        A = 0x06;                                    /* L7E0A  MAKE INTO 4 MS */
        CYC(2);
        hw_wr8(E1024T, A);                           /* L7E0C  START UP THE TIMER AGAIN */
        M8(SYNC) = inc8(M8(SYNC));                   /* L7E0E  KICK THE MAINLINE */
        CYC(13);
        if (CCV) { s_firq(); return; }               /* L7E10  B RESET US IF MAINLINE IS STUCK */
    }
l_rirq_80:;
    CK(0x7E12);
    /* X-->COMMAND BUFFER */
    /* B:= DISP INTO COMMAND BUFFER, LATEST COMMAND */
    A = hw_rd8(PAD);                                 /* L7E12  CHECK MAIN BYTE FLAG (SAFER THAN PIA7 EDGE) */
    CYC(7);
    if ((A & 0x80)) {                                /* L7E14  IFMI  ?ANOTHER COMMAND WAITING? */
        A = hw_rd8(RIF);                             /* L7E16  CLEAR ANY PIA7 EDGE TO CLEAR THE IRQ */
        CYC(4);
        A = hw_rd8(SIN);                             /* L7E18  MUST CLEAR PIA7 EDGE BEFORE TELLING MAIN PCB */
        nz8(A);
        CYC(8);
        if (CCZ) { s_firq(); return; }               /* L7E1B  RESET IF SUPERCOMMAND 0 IS SENT */
        /* X-->COMMAND BUFFER */
        /* B:= DISP INTO COMMAND BUFFER, LATEST COMMAND */
        B = (uint8_t)(B + 1);                        /* L7E1D  NEXT LOC */
        B &= 0x1F;                                   /* L7E1E  HANDLE WRAPAROUND */
        wr8((uint16_t)(X + (int8_t)B), A);           /* L7E20 */
        CYC(12);
        goto l_rirq_80;                              /* L7E22  LOOP AGAIN QUICKLY TO HANDLE SEQUENTIAL REQUESTS */
    }
    /* X-->COMMAND BUFFER */
    /* B:= DISP INTO COMMAND BUFFER, LATEST COMMAND */
    M8(CMDTOP) = B;                                  /* L7E24  SAVE OUR TOP OF COMMAND POINTER */
    CYC(19);
    return;                                          /* L7E26 */
}

/* FIRQ ($7E27) - BREAKPOINTS FOR ROM ONLY
 * Condition codes in: NZVC; out: C.
 */
void s_firq(void)
{
    CK(0x7E27);
    sw_sei();                                        /* L7E27  SEI  JUST HOPE THE PROCESSOR AT LEAST FUNCTIONS */
    CYC(3);
    A = hw_rd8(SIN);                                 /* L7E29  MAIN BOARD DIAG, CLEAR INPUT */
    S = 0x107F;                                      /* L7E2C  STACK WILL BE IN 6532 RAM */
    A = 0x10;                                        /* L7E30 */
    DP = A;                                          /* L7E32  DIRECT PAGE WILL ALSO BE IN 6532 RAM */
    A = 0xFF;                                        /* L7E34  SET UP PBD AS OUTPUTS */
    CYC(19);
    hw_wr8(PBDD, A);                                 /* L7E36 */
    CYC(4);
    hw_wr8(PBD, A);                                  /* L7E38  ALL ONES IS THE SAFEST */
    CYC(4);
    hw_wr8(PAD, A);                                  /* L7E3A  MAKE SURE CONTROL STROBES ARE HIGH */
    B = 0x2B;                                        /* L7E3C  SET UP PAD */
    CYC(6);
    hw_wr8(PADD, B);                                 /* L7E3E */
    /* PROVIDE SLOP TIME FOR MAIN DIAG */
    X = P_SND;                                       /* L7E40  INIT POKEYS */
    D = 0x0000;                                      /* L7E43 */
    CYC(10);
l_init_20:;
    CK(0x7E46);
    wr16(X, D);                                      /* L7E46 */
    X = (uint16_t)(X + 2);
    CYC(15);
    if (X < P_SNDZ_1820) goto l_init_20;             /* L7E4B */
    A = hw_rd8(SIN);                                 /* L7E4D  MAIN BOARD DIAG -- LOOP BACK DATA */
    CYC(5);
    hw_wr8(SOUT, A);                                 /* L7E50 */
    X = RAM;                                         /* L7E53  CLEAR RAM */
    D = 0x0000;                                      /* L7E56 */
    CYC(11);
l_init_10:;
    CK(0x7E59);
    wr16(X, D);                                      /* L7E59 */
    X = (uint16_t)(X + 2);
    CYC(15);
    if (X < RAMZ) goto l_init_10;                    /* L7E5E */
    X = DPRAM;                                       /* L7E60 */
    CYC(3);
    do {
        CK(0x7E63);
        wr16(X, D);                                  /* L7E63 */
        X = (uint16_t)(X + 2);
        CYC(15);
    } while (X < DPRAMZ);                            /* L7E68  HSEND   */
    hw_wr8(P_BGN1, A);                               /* L7E6A  BEGIN POKEY INIT-ALLOW TIME TO SETTLE. */
    CYC(5);
    hw_wr8(P_BGN2, A);                               /* L7E6D */
    CYC(5);
    hw_wr8(P_BGN3, A);                               /* L7E70 */
    CYC(5);
    hw_wr8(P_BGN4, A);                               /* L7E73 */
    CYC(5);
    hw_wr8(P_ACT1, A);                               /* L7E76 */
    CYC(5);
    hw_wr8(P_ACT2, A);                               /* L7E79 */
    CYC(5);
    hw_wr8(P_ACT3, A);                               /* L7E7C */
    CYC(5);
    hw_wr8(P_ACT4, A);                               /* L7E7F */
    A = 0x07;                                        /* L7E82  FAST SCAN */
    CYC(7);
    hw_wr8(P_BGN1, A);                               /* L7E84 */
    CYC(5);
    hw_wr8(P_BGN2, A);                               /* L7E87  FINISH POKEY INIT */
    CYC(5);
    hw_wr8(P_BGN3, A);                               /* L7E8A */
    CYC(5);
    hw_wr8(P_BGN4, A);                               /* L7E8D */
    CYC(5);
    A = hw_rd8(TESTSW);                              /* L7E90  TEST SWITCH ON? */
    A &= TESTBT;                                     /* L7E92 */
    CYC(9);
    if (A == 0) {                                    /* L7E94  IFEQ  YES */
        A = hw_rd8(PAD);                             /* L7E96  TURN OFF FM (VIBRATO) FOR SELF TEST TONES */
        A |= 0x08;                                   /* L7E98 */
        CYC(6);
        hw_wr8(PAD, A);                              /* L7E9A */
        CYC(7);
        s_test(); return;                            /* L7E9C  GO TO TEST */
    }
    A = hw_rd8(PAD);                                 /* L7E9E  TURN FM ON */
    A &= 0xF7;                                       /* L7EA0 */
    CYC(6);
    hw_wr8(PAD, A);                                  /* L7EA2 */
    A = 0x3F;                                        /* L7EA4  TRAP OUT FIRST BYTE RAM */
    M8(S_GARBG) = A;                                 /* L7EA6 */
    CYC(18);
    JSR(s_isnd);                                     /* L7EA8  PM MUSIC INITIALIZOR */
    CYC(8);
    JSR(s_spkres);                                   /* L7EAB  RESET SPEECH CHIP/ROUTINE */
    A = hw_rd8(RIF);                                 /* L7EAE  MAKE SURE PA7 FLAG IS RESET */
    CYC(4);
    A = hw_rd8(SIN);                                 /* L7EB0  AND THEN CLEAR MAINFLAG SO MAIN PCB CAN TALK AGAIN */
    A = PBXS_OK;                                     /* L7EB3  OK VAL FOR THIS VERSION */
    CYC(7);
    hw_wr8(SOUT, A);                                 /* L7EB5  TELL CURIOUS MAIN PCB THAT WE ARE GOING AGAIN */
    A = 0x06;                                        /* L7EB8  SET UP 4 MS IRQ TIMER */
    CYC(7);
    hw_wr8(E1024T, A);                               /* L7EBA */
    CYC(4);
    hw_wr8(EIPED, A);                                /* L7EBC  ENABLE PA7 INTERRUPTS WITH POSITIVE EDGE DETECTS */
    nz8(A);
    CYC(8);
    s_main(); return;                                /* L7EBE */
}

/* TEST ($7ED1) - RAM TEST FIRST
 * Condition codes out: C.
 */
void s_test(void)
{
    uint16_t t16;
    CK(0x7ED1);
    A = 0x00;                                        /* L7ED1  SET FLAG FOR NO ERRORS */
    U = TRAMP;                                       /* L7ED3 */
    CYC(5);
    do {
        CK(0x7ED6);
        X = rd16(U);                                 /* L7ED6  STARTING ADDRESS */
        Y = (uint16_t)(X + 1);                       /* L7ED8  STARTING PATTERN IS ADDRESS + 1 */
        CYC(10);
        do {
            CK(0x7EDA);
            wr16(X, Y);                              /* L7EDA  STORE ADDRESS IN RAM */
            X = (uint16_t)(X + 2);
            Y = (uint16_t)(Y - 0xFF);                /* L7EDD  NEXT PATTERN */
            t16 = rd16((uint16_t)(U + 2));           /* L7EE1 */
            CYC(27);
        } while (X < t16);                           /* L7EE3  HSEND   */
        X = rd16(U);                                 /* L7EE5  STARTING ADDRESS */
        Y = (uint16_t)(X + 1);                       /* L7EE7  STARTING PATTERN */
        CYC(10);
        do {
            CK(0x7EE9);
            t16 = rd16(X);                           /* L7EE9  CHECK RAM FOR DATA STORED */
            X = (uint16_t)(X + 2);
            CYC(13);
            if (Y != t16) {                          /* L7EEC  IFNE  ERROR -- SET APPROPRIATE BIT */
                A |= rd8((uint16_t)(U + 4));         /* L7EEE  OR I ERROR CODE */
                CYC(5);
            }
            Y = (uint16_t)(Y - 0xFF);                /* L7EF0  NEXT WORD */
            t16 = rd16((uint16_t)(U + 2));           /* L7EF4  ENDING ADDRESS? */
            CYC(18);
        } while (X < t16);                           /* L7EF6  HSEND  IF SO, DONE */
        U = (uint16_t)(U + 5);                       /* L7EF8  DO NEXT RAM */
        /* CMPU TRAMPZ */                            /* L7EFA  END OF RAM TABLE? */
        CYC(13);
    } while (U < TRAMPZ);                            /* L7EFE  HSEND   */
    /* ROM TEST */
    Y = D;                                           /* L7F00  SAVE CURRENT ERRORS */
    U = TROMP;                                       /* L7F02  TABLE OF ROMS */
    CYC(9);
    do {
        CK(0x7F05);
        X = rd16(U);                                 /* L7F05  STARTING ADDRESS */
        U = (uint16_t)(U + 2);
        D = X;                                       /* L7F07  USE STARTING ADDRESS AS SEED */
        CYC(14);
        do {
            CK(0x7F09);
            D = (uint16_t)(D + rd16(X));             /* L7F09 */
            X = (uint16_t)(X + 2);
            t16 = rd16(U);                           /* L7F0B  AT ENDING ADDRESS? ( NEXT TABLE ENTRY IS ALSO ENDING ADDRESS ) */
            CYC(18);
        } while (X < t16);                           /* L7F0D  HSEND   */
        wr16(X, D);                                  /* L7F0F  USE ANALYZER FOR CHECKSUM */
        CYC(8);
        if (D != 0) {                                /* L7F11  IFNE  ERROR */
            D = Y;                                   /* L7F13  RETRIEVE ERRORS TO DATE */
            CYC(13);
            if (X < (ROM1+0x10)) {                   /* L7F18  IFLO  ROM 0 */
                A |= 0x04;                           /* L7F1A */
                CYC(5);
            } else {                                 /* L7F1C  ELSE  ROM 1 */
                A |= 0x08;                           /* L7F1E */
                CYC(2);
            }
            Y = D;                                   /* L7F20  SAVE IT IN Y AGAIN */
            CYC(6);
        }
        /* CMPU TROMPZ */                            /* L7F22  DONE? */
        CYC(8);
    } while (U < TROMPZ);                            /* L7F26  HSEND   */
    /* REPORT ERRORS/NON-ERRORS VIA POKEY */
    D = Y;                                           /* L7F28  GET ERRORS IN A */
    B = 0x03;                                        /* L7F2A */
    CYC(8);
    do {
        CK(0x7F2C);
        A = lsr8(A);                                 /* L7F2C  SHIFT CODE TO CARRY */
        CYC(5);
        if (CCC) {                                   /* L7F2D  IFCS  ERROR */
            U = 0xCFA8;                              /* L7F2F  LOW TONE ON POKEY 0 MEANS ERROR */
            CYC(3);
            hw_wr16(P_SND, U);                       /* L7F32  POKEY 0 VOICE 0 */
            CYC(9);
        } else {                                     /* L7F35  ELSE   */
            U = 0x20A8;                              /* L7F37  HI TONE ON POKEY 1 MEANS OK */
            CYC(3);
            hw_wr16(P_SND+0xA, U);                   /* L7F3A  POKEY 1 VOICE 1 */
            CYC(6);
        }
        X = 0x8000;                                  /* L7F3D  DELAY WHILE SOUND IS ON */
        CYC(3);
        do {
            CK(0x7F40);
            X = (uint16_t)(X - 1);                   /* L7F40 */
            CYC(8);
        } while (X != 0);                            /* L7F42  EQEND   */
        U = 0x0000;                                  /* L7F44  TURN OFF SOUNDS */
        CYC(3);
        hw_wr16(P_SND, U);                           /* L7F47 */
        CYC(6);
        hw_wr16(P_SND+0xA, U);                       /* L7F4A */
        X = 0x8000;                                  /* L7F4D  NOW DELAY FOR THE QUIET */
        /* TSTB */                                   /* L7F50 */
        CYC(14);
        if (B == 0) {                                /* L7F51  IFEQ  LAST DELAY, MAKE IT A LONG ONE */
            X = (uint16_t)(X + 0x7FFF);              /* L7F53 */
            CYC(8);
        }
        do {
            CK(0x7F57);
            X = (uint16_t)(X - 1);                   /* L7F57 */
            CYC(8);
        } while (X != 0);                            /* L7F59  EQEND   */
        B = dec8(B);                                 /* L7F5B  DONE WITH ALL DEVICES */
        CYC(5);
    } while (!CCN);                                  /* L7F5C  MIEND   */
    CYC(4);
    s_reset(); return;                               /* L7F5E */
}
